), candidates AS (
  SELECT m.id AS module_id, s.title, s.content, s.position
  FROM seed s JOIN lms_courses c ON c.code = s.code
  JOIN modules m ON m.course_id = c.id AND m.title = s.title
  WHERE NOT EXISTS (SELECT 1 FROM lessons l WHERE l.module_id = m.id)
)
